        out(f'EXPLOIT_FAIL: charge returned {r.status_code}')
    r = s.get(f'{BASE}/api/payments/logs', timeout=3)
    if r.status_code != 200:
        out(f'EXPLOIT_FAIL: logs endpoint returned {r.status_code}')
